          "WASAIのハーフラック(MK780)は幅124cm×奥行100cm×高さ209/220cmで¥25,990、評価4.4(291件)です。19段階の高さ調節機能により、ベンチプレス・スクワット・懸垂・ディップスが1台でこなせます。耐荷重150kgで家庭用としては十分な強度があり、6畳の部屋なら他の器具と組み合わせても余裕を持って配置できます。"
