          "7 Life 割れない鏡は180×80cmの大型サイズで¥18,800、評価4.4(101件)です。ポリエステル製で割れる心配がなく、厚さ2cmの薄型設計でスペースを取りません。マグネット式で壁に簡単に取り付けられ、賃貸住宅でも壁を傷つけずに設置可能です。立てかけ使用もできるため、トレーニング時だけ設置する使い方もできます。"
