    "title": "ホームジム後悔しないための完全ガイド|失敗例と対策",
    "excerpt": "ホームジム作りでよくある後悔ポイントを実例とともに解説。床補強・騒音・スペース・予算の失敗を防ぎ、長く使える環境を作るための具体的な対策をまとめました。",
