          "正しいフォームでは、肘は常に軽く曲げた状態(約150度)をキープし、肩甲骨を寄せたままダンベルを弧を描くように下ろします。胸の外側にストレッチ感を感じながら、ゆっくり3秒かけて下ろし、2秒で上げるテンポが理想的です。10回×3セットを正しいフォームで完遂できない場合は、迷わず1〜2kg軽くしましょう。"
