          "よくある失敗は、肘を体幹から離しすぎて肩関節に負担をかけること、肩がベンチから浮いて僧帽筋で支えてしまうこと、ダンベルを真上に挙げて負荷が抜けることです。特に重量を上げると肩が前に出やすくなるため、軽い重量でフォームを固めてから段階的に負荷を増やしてください。"
